def fill_location_full_path(apps, schema_editor):
    Location = apps.get_model('bibasset', 'Location')
    locs = {loc.pk: loc for loc in Location.objects.all()}

    def path(loc, seen=()):
        if not loc.parent_id or loc.parent_id not in locs or loc.pk in seen:
            return loc.name
        return f"{path(locs[loc.parent_id], seen + (loc.pk,))} > {loc.name}"

    for loc in locs.values():
        loc.full_path = path(loc)
    Location.objects.bulk_update(locs.values(), ['full_path'])


def link_corrective_schedules(apps, schema_editor):
    """Jadwal lama hanya ditandai lewat teks notes '[CORRECTIVE - Laporan Kerusakan #ID]'."""
    MaintenanceSchedule = apps.get_model('bibasset', 'MaintenanceSchedule')
    DamageReport = apps.get_model('bibasset', 'DamageReport')
    report_ids = set(DamageReport.objects.values_list('pk', flat=True))
    pattern = re.compile(r'^\[CORRECTIVE - Laporan Kerusakan #(\d+)\]')

    to_update = []
    for sch in MaintenanceSchedule.objects.filter(notes__startswith='[CORRECTIVE'):
        m = pattern.match(sch.notes)
        if m and int(m.group(1)) in report_ids:
            sch.damage_report_id = int(m.group(1))
            to_update.append(sch)
    MaintenanceSchedule.objects.bulk_update(to_update, ['damage_report'])


